import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"镶嵌流程","description":"","frontmatter":{},"headers":[],"relativePath":"modules/gem/process.md","filePath":"modules/gem/process.md","lastUpdated":0}`),a={name:`modules/gem/process.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="镶嵌流程" tabindex="-1">镶嵌流程 <a class="header-anchor" href="#镶嵌流程" aria-label="Permalink to “镶嵌流程”">​</a></h1><p>Gem 镶嵌流程负责校验目标装备、插槽物品配置、宝石物品、插槽状态和费用，然后把宝石数据写入装备并重建展示。排查时先确认装备是否匹配 <code>items/*.yml</code>，再看宝石兼容性和插槽状态。</p><h2 id="流程步骤" tabindex="-1">流程步骤 <a class="header-anchor" href="#流程步骤" aria-label="Permalink to “流程步骤”">​</a></h2><ol><li>玩家打开宝石 GUI 或执行宝石相关命令。镶嵌、开孔、升级界面打开时目标槽为空，不会自动从玩家主手或背包克隆/转移装备。</li><li>模块读取目标装备，并通过 <code>items/*.yml</code> 顶层的 <code>matcher</code> 与 <code>slot_groups</code> 确定适用的插槽物品配置。</li><li>读取 <code>slots</code>，过滤未开放、已占用或不允许当前操作的槽位。</li><li>读取宝石定义，检查宝石 <code>socket_compatibility</code> 是否兼容 <code>slots[].type</code>。</li><li>检查插槽物品级限制，例如 <code>allowed_gem_types</code>、<code>max_same_type</code>、<code>max_same_id</code>。</li><li>检查条件与费用，例如 <code>inlay_cost</code>、<code>extract_cost</code>、开孔器或升级材料。</li><li>写入装备 PDC，记录宝石 ID、当前等级、槽位索引和 gem layer 数据。</li><li>通过 CoreLib 的物品操作账本（<code>ItemOperationLedger</code>）重建名称、Lore、属性 payload 和技能 payload。</li><li>重新评估宝石共鸣，并应用或撤销共鸣效果。</li><li>执行动作并刷新玩家背包。</li></ol><h2 id="关键校验字段" tabindex="-1">关键校验字段 <a class="header-anchor" href="#关键校验字段" aria-label="Permalink to “关键校验字段”">​</a></h2><table tabindex="0"><thead><tr><th>配置位置</th><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>items/*.yml</code></td><td><code>matcher</code> + <code>slot_groups</code></td><td>哪些物品会获得这套插槽配置。见<a href="./templates.html#匹配规则-matcher-slot-groups">模板与插槽</a>。</td></tr><tr><td><code>items/*.yml</code></td><td><code>slots[].type</code></td><td>插槽类型，例如 <code>attack</code>、<code>defense</code>、<code>universal</code>。</td></tr><tr><td><code>items/*.yml</code></td><td><code>default_open_slots</code></td><td>初始开放的插槽索引。未列出的插槽需要开孔。</td></tr><tr><td><code>items/*.yml</code></td><td><code>allowed_gem_types</code></td><td>装备允许镶嵌的宝石类型白名单。</td></tr><tr><td><code>items/*.yml</code></td><td><code>max_same_type</code></td><td>同类型宝石最大数量。未配置时不限制。</td></tr><tr><td><code>items/*.yml</code></td><td><code>max_same_id</code></td><td>同 ID 宝石最大数量，默认 1。</td></tr><tr><td><code>gems/*.yml</code></td><td><code>gem_type</code></td><td>宝石自身类型。</td></tr><tr><td><code>gems/*.yml</code></td><td><code>socket_compatibility</code></td><td>宝石可放入哪些插槽类型。</td></tr><tr><td><code>gems/*.yml</code></td><td><code>inlay_cost</code> / <code>extract_cost</code></td><td>镶嵌与提取费用。</td></tr></tbody></table><div class="important custom-block"><p class="custom-block-title custom-block-title-default">IMPORTANT</p><p>旧文档中出现过 <code>slot_types</code>，当前源码使用的是 <code>socket_compatibility</code> 与 <code>slots[].type</code>。</p></div><h2 id="排查入口" tabindex="-1">排查入口 <a class="header-anchor" href="#排查入口" aria-label="Permalink to “排查入口”">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先检查</th></tr></thead><tbody><tr><td>装备不支持宝石</td><td><code>items/*.yml</code> 顶层的 <code>matcher</code> 与 <code>slot_groups</code> 是否匹配目标装备。</td></tr><tr><td>找不到可用插槽</td><td><code>slots</code>、<code>default_open_slots</code>、插槽是否已占用。</td></tr><tr><td>宝石无法放入</td><td><code>gems/*.yml &gt; socket_compatibility</code> 与 <code>slots[].type</code> 是否一致。</td></tr><tr><td>同类宝石超限</td><td><code>allowed_gem_types</code>、<code>max_same_type</code>、<code>max_same_id</code>。</td></tr><tr><td>属性不生效</td><td>EmakiAttribute 是否安装，宝石效果是否写入 <code>ea_attribute</code>。</td></tr></tbody></table><h2 id="边界情况" tabindex="-1">边界情况 <a class="header-anchor" href="#边界情况" aria-label="Permalink to “边界情况”">​</a></h2><ul><li>装备没有匹配的插槽物品配置：提示该装备不支持宝石。</li><li>插槽未开放：需要先通过开孔器解锁。</li><li>插槽已占用：禁止覆盖，除非进入提取或替换相关流程。</li><li>宝石物品堆叠：通常只消耗 1 个，剩余数量保留。</li><li>背包满：提取宝石时应放入背包或安全掉落。</li><li>GUI 打开：目标装备和材料必须由玩家手动放入；模块不会自动读取主手作为初始槽位，避免误吞或误移动物品。</li><li>配置重载：已镶嵌旧宝石会尽量保留 ID，并在展示重建时做兜底处理。宝石本体在获取、重载和 GUI 复刻时会按当前定义刷新名称、Lore、模型与等级展示。</li></ul>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};